import{_ as d,o as e,c as o,a as r}from"./chunks/framework.Ld7uezS_.js";const b=JSON.parse('{"title":"检测维修保养方向标准映射表","description":"","frontmatter":{},"headers":[],"relativePath":"standard-mapping.md","filePath":"standard-mapping.md","lastUpdated":1787292351000}'),a={name:"standard-mapping.md"};function c(l,t,i,S,h,s){return e(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="检测维修保养方向标准映射表" tabindex="-1">检测维修保养方向标准映射表 <a class="header-anchor" href="#检测维修保养方向标准映射表" aria-label="Permalink to &quot;检测维修保养方向标准映射表&quot;">​</a></h1><blockquote><p>本表是课程审查与学习导航，不替代《消防设施操作员国家职业技能标准（2019年版）》原文、考核大纲、官方教材或报考地当批次评分表。</p><p><strong>核验状态说明</strong>：本轮检查了 2019 年版职业标准 PDF 的可读性，并发现官方文件为图像/压缩内容，当前无法可靠读取 2.1—5.3 的完整原文，因此暂不伪造页码、原句或逐条技能要求。公开检索到的 2019 年版摘要可确认职业功能和部分条目，但摘要页面不作为唯一原文证据；2026 年版已公开且计划于 2026-10-01 起施行，须作为版本过渡事项单独复核。</p></blockquote><h2 id="一、方向范围" tabindex="-1">一、方向范围 <a class="header-anchor" href="#一、方向范围" aria-label="Permalink to &quot;一、方向范围&quot;">​</a></h2><p>检测维修保养方向的课程主线按四项职业功能组织：</p><table tabindex="0"><thead><tr><th>职业功能</th><th>本站课程入口</th><th>学习结果</th><th>当前状态</th></tr></thead><tbody><tr><td>2. 设施操作</td><td><a href="/skill/02-operation">/skill/02-operation</a>；报警、水系统、其他设施项目卡</td><td>能先识别任务类型，核对位置/区域/对象/目的，再确认授权、安全条件和控制方式，执行操作并核对反馈、恢复和记录</td><td>已补“任务—对象—区域—目的—完成标准”零基础前置课；仍需按标准条目细化</td></tr><tr><td>3. 设施保养</td><td><a href="/skill/03-maintenance">/skill/03-maintenance</a>；三类设备项目卡</td><td>能按外观、连接、状态、功能、记录组织保养</td><td>已建立框架，需补周期/项目/判定映射</td></tr><tr><td>4. 设施维修</td><td><a href="/skill/04-repair">/skill/04-repair</a>；报警、水系统、其他设施项目卡</td><td>能按现象、判断、安全隔离、处理、验证、报告闭环</td><td>本轮优先补强</td></tr><tr><td>5. 设施检测</td><td><a href="/skill/05-detection">/skill/05-detection</a>；报警、水系统、其他设施项目卡</td><td>能按方案记录输入、显示、动作、反馈、恢复和判定依据</td><td>本轮优先补强</td></tr></tbody></table><blockquote><p>设施监控页面用于读懂控制器状态、报警、故障、监管、屏蔽/隔离和反馈，是本方向的基础能力，不在本表中作为检测维修保养方向的独立核心职业功能。</p></blockquote><h2 id="二、2-1—5-3-映射框架" tabindex="-1">二、2.1—5.3 映射框架 <a class="header-anchor" href="#二、2-1—5-3-映射框架" aria-label="Permalink to &quot;二、2.1—5.3 映射框架&quot;">​</a></h2><p>下表中的“标准条目摘要”是课程归类用语，不是标准原文转录。待获取可搜索标准原文后，应补充页码、原句摘要和逐条核验日期。</p><table tabindex="0"><thead><tr><th>编号</th><th>课程归类主题</th><th>对应页面/项目卡</th><th>只读训练入口</th><th>来源状态</th><th>下一步</th></tr></thead><tbody><tr><td>2.1</td><td>火灾自动报警系统操作</td><td><code>/skill/02-operation</code>、<code>/skill/alarm-system</code></td><td><code>S02</code>、<code>S19</code>、<code>S26-S31</code>、报警项目卡场景</td><td>已补设备差异、六类核心设备零基础学习卡、闭环检测和只读场景；分项原文待复核</td><td>按鉴定站评分点继续核对探测器、手报、主机、模块、主备电</td></tr><tr><td>2.2</td><td>自动灭火系统操作</td><td><code>/skill/02-operation</code>、<code>/skill/water-system</code></td><td><code>S02</code>、<code>S20</code>、<code>S32-S37</code>、水系统场景</td><td>已补六类水系统设备零基础学习卡，覆盖水池/水箱、泵组、阀组、水流/压力反馈、末端试水、接合器/消火栓/喷头；湿式/干式边界已标注</td><td>按鉴定站评分点继续核对泵组、报警阀组、末端试水和恢复步骤</td></tr><tr><td>2.3</td><td>其他消防设施操作</td><td><code>/skill/02-operation</code>、<code>/skill/other-facilities</code></td><td><code>S02</code>、<code>S21-S22</code>、<code>S46</code>、<code>S49</code>、其他设施场景</td><td>已补七类其他设施零基础设备卡，覆盖防烟排烟、分隔构件、应急照明/指示、电话/广播、电梯、灭火器和消火栓；检测闭环和故障专项已建立</td><td>按鉴定站评分点继续核对风机风阀、卷帘、照明、广播电话等对象卡</td></tr><tr><td>3.1</td><td>火灾自动报警系统保养</td><td><code>/skill/03-maintenance</code>、<code>/skill/alarm-system</code></td><td><code>S03、S15、S26-S27</code>、报警保养要点</td><td>已补设备级前置、六类核心设备的正常证据/异常边界、状态确认和记录边界；周期/项目待按依据核对</td><td>继续补标准条目、周期和项目判定映射</td></tr><tr><td>3.2</td><td>自动灭火系统保养</td><td><code>/skill/03-maintenance</code>、<code>/skill/water-system</code></td><td><code>S03、S16</code>、水系统保养要点</td><td>已同步六类设备的外观、连接、状态、功能和记录入口；周期/项目待按依据核对</td><td>继续补阀门、泵组、水源、试水排水映射</td></tr><tr><td>3.3</td><td>其他消防设施保养</td><td><code>/skill/03-maintenance</code>、<code>/skill/other-facilities</code></td><td><code>S03、S17-S18</code>、其他设施保养要点</td><td>已同步七类设备的外观、连接、状态、功能和记录入口；周期/项目待按依据核对</td><td>继续补防排烟、卷帘、照明、灭火器映射</td></tr><tr><td>4.1</td><td>火灾自动报警系统维修</td><td><code>/skill/04-repair</code>、<code>/skill/alarm-system</code></td><td><code>S04</code>、<code>S26-S31</code>、<code>S44</code>、<code>S47</code>、报警场景 A（12例）</td><td>已补探测器、手报、警报器、模块、输出、主备电、回路/通信六类核心设备学习卡及故障闭环；标准原文和授权边界待逐条复核</td><td>按型号和授权边界继续核对故障代码、测试方法和维修权限</td></tr><tr><td>4.2</td><td>自动灭火系统维修</td><td><code>/skill/04-repair</code>、<code>/skill/water-system</code></td><td><code>S04</code>、<code>S45</code>、<code>S48</code>、水系统场景（12例）</td><td>已补六类设备的故障分层、保护影响、临时防护、复测和恢复入口；具体维修权限待按依据核对</td><td>按系统形式继续核对泵组、阀组、末端试水和恢复步骤</td></tr><tr><td>4.3</td><td>其他消防设施维修</td><td><code>/skill/04-repair</code>、<code>/skill/other-facilities</code></td><td><code>S04</code>、<code>S46</code>、<code>S49</code>、其他设施场景（12例）</td><td>已同步七类设备的故障分层、人员/保护影响、临时防护、专业协同、复测和恢复入口；标准原文待复核</td><td>按设备型号、专业协同和授权边界继续核对维修方法</td></tr><tr><td>5.1</td><td>火灾自动报警系统检测</td><td><code>/skill/05-detection</code>、<code>/skill/alarm-system</code></td><td><code>S05</code>、<code>S26-S31</code>、报警检测卡</td><td>已补六类核心设备的是什么/结构/原理/正常证据/异常/边界/记录，以及对象—依据—证据—影响—停止条件和五项结果；仪器和判定依据仍待核验</td><td>按适用依据补仪器、方法、记录、复测和报告字段</td></tr><tr><td>5.2</td><td>自动灭火系统检测</td><td><code>/skill/05-detection</code>、<code>/skill/water-system</code></td><td><code>S05</code>、<code>S32-S37</code>、水系统检测卡</td><td>已补六类设备的检测前置、方法、三类证据、异常分层、复测和记录边界；湿式/干式边界已标注；数值不得泛化</td><td>增加泵组、报警阀、末端试水、反馈判定的依据字段</td></tr><tr><td>5.3</td><td>其他消防设施检测</td><td><code>/skill/05-detection</code>、<code>/skill/other-facilities</code></td><td><code>S05</code>、<code>S38-S43</code>、<code>S46</code>、<code>S49</code>、其他设施检测卡</td><td>已同步七类设备的对象差异、前置安全、动作/反馈、恢复和记录入口；八类故障案例已建立；仪器和判定依据仍需按项目补充</td><td>按防排烟、卷帘、照明、广播电话、电梯和器材组件继续补依据字段</td></tr></tbody></table><h2 id="三、十章理论到职业功能逐项关联表" tabindex="-1">三、十章理论到职业功能逐项关联表 <a class="header-anchor" href="#三、十章理论到职业功能逐项关联表" aria-label="Permalink to &quot;三、十章理论到职业功能逐项关联表&quot;">​</a></h2><table tabindex="0"><thead><tr><th>理论章节</th><th>原理关注点</th><th>2.设施操作</th><th>3.设施保养</th><th>4.设施维修</th><th>5.设施检测</th><th>训练题索引</th></tr></thead><tbody><tr><td>1. 职业道德</td><td>证据真实、复核、报告</td><td>操作结果如实记录</td><td>异常不隐瞒</td><td>未排除不写已修复</td><td>原始/复测/结论分开</td><td>T01、T15、T28；S01、S06、S23</td></tr><tr><td>2. 消防工作概述</td><td>单位责任、岗位协同</td><td>报警与联动报告</td><td>交接和异常报告</td><td>保护影响升级</td><td>责任、范围、依据留痕</td><td>T02、T16、T29；S01、S25</td></tr><tr><td>3. 燃烧和火灾</td><td>燃烧、烟气、灭火边界</td><td>初起处置和设备选择</td><td>器材与环境检查</td><td>复燃/环境因素排查</td><td>测试前安全与现场保护</td><td>T03-T04、T30、T34；S06、S25、S43</td></tr><tr><td>4. 建筑防火</td><td>防火分区、防烟分区、防火间距、耐火极限、耐火等级、疏散与防烟分隔</td><td>卷帘、风阀、门动作</td><td>分隔设施状态</td><td>障碍、限位、反馈</td><td>区域、动作、恢复记录</td><td>T20-T21、T31、T38-T39；S21、S38-S39、S46</td></tr><tr><td>5. 电气消防</td><td>电源、回路、接地、保护</td><td>控制柜与主备电操作</td><td>接线、端子、供电状态</td><td>供电/线路/本体分层</td><td>电气测量与隔离</td><td>T06、T22、T32；S08、S26、S30、S47</td></tr><tr><td>6. 消防设施</td><td>信号链与系统组成</td><td>报警、泵组、联动</td><td>组成、状态、功能</td><td>模块、泵组、阀组、风阀</td><td>输入/显示/动作/反馈/恢复</td><td>T08-T10、T23-T24、T33；S02、S19-S22、S26-S49</td></tr><tr><td>7. 初起火灾处置</td><td>报警、疏散、复燃</td><td>报警和现场保护</td><td>器材可用性</td><td>停用与临时防护</td><td>清场、通知、恢复</td><td>T07、T11、T17、T34；S01、S21、S25</td></tr><tr><td>8. 计算机基础</td><td>界面、日志、通信</td><td>查询、消音、复位</td><td>记录和显示检查</td><td>信息/权限/通信排查</td><td>时间、地址、原始记录</td><td>T13、T18、T25、T35；S01、S07、S09、S31</td></tr><tr><td>9. 法律法规与技术标准</td><td>依据、版本、权限</td><td>按说明书/规程操作</td><td>按适用项目检查</td><td>授权、停用、复测</td><td>方法、仪器、判定依据</td><td>T05、T12、T26、T36；S04、S05、S11-S14</td></tr><tr><td>10. 安全生产与职业健康</td><td>隔离、监护、清场</td><td>前置安全与恢复</td><td>PPE和现场条件</td><td>断电验电、升级</td><td>仪器安全与复原</td><td>T14、T19、T27、T37；S04、S07-S10、S12、S21</td></tr></tbody></table><blockquote><p>本表是课程学习关联，不是标准原文逐条转录；题号是本站原创训练题/场景题编号，不冒充官方题库。涉及具体数值、权限和评分点仍须回查适用依据。</p></blockquote><h2 id="四、综合复习与阶段门槛" tabindex="-1">四、综合复习与阶段门槛 <a class="header-anchor" href="#四、综合复习与阶段门槛" aria-label="Permalink to &quot;四、综合复习与阶段门槛&quot;">​</a></h2><table tabindex="0"><thead><tr><th>复习阶段</th><th>学完应会</th><th>不会时回看</th><th>进入下一阶段条件</th></tr></thead><tbody><tr><td>理论串联</td><td>十章各能写出一条原理→设备行为因果句</td><td>对应理论页与 T01-T39</td><td>十章各完成至少一张题卡并能解释错项</td></tr><tr><td>设备横向</td><td>报警、水系统、其他设施各自说清组成、动作、反馈、故障、恢复</td><td>三类设备项目卡与 S26-S49</td><td>每类至少能完成一次完整闭环复述</td></tr><tr><td>职业功能纵向</td><td>用同一设备区分操作、保养、维修、检测的目的和证据</td><td><code>/skill/02-operation</code> 至 <code>/skill/05-detection</code>、S02-S18</td><td>能按四项功能分别写出记录字段</td></tr><tr><td>综合场景</td><td>先判断影响、授权和安全，再给处理、复测、报告</td><td>S23-S25 及相关专项题</td><td>不把一次动作、一次读数或复位直接写成合格</td></tr><tr><td>依据收口</td><td>能标出标准/方案/说明书/地方公告的适用边界</td><td><code>/sources</code>、<code>/exam-guide</code> 和项目卡依据字段</td><td>所有固定数值和评分点都有待核验或明确来源状态</td></tr></tbody></table><h2 id="五、训练覆盖核对表" tabindex="-1">五、训练覆盖核对表 <a class="header-anchor" href="#五、训练覆盖核对表" aria-label="Permalink to &quot;五、训练覆盖核对表&quot;">​</a></h2><p>这张表只回答“映射条目是否有可阅读的训练入口”，不代表官方题量、鉴定站评分点或标准原文已经全部核验。</p><table tabindex="0"><thead><tr><th>职业功能</th><th>基础操作/概念</th><th>异常或边界</th><th>恢复/记录判定</th><th>当前题卡</th><th>覆盖状态</th></tr></thead><tbody><tr><td>2. 设施操作</td><td>S02</td><td>S19、S20、S21、S26、S28</td><td>S22、S06、S31</td><td>S02、S06、S19-S22、S26-S31</td><td>框架已覆盖，设备分项和标准ID待补</td></tr><tr><td>3. 设施保养</td><td>S03</td><td>S15、S16、S17、S26、S27</td><td>S18</td><td>S03、S15-S18、S26-S27</td><td>框架已覆盖，周期/项目判定待核验</td></tr><tr><td>4. 设施维修</td><td>S04、S07、S26、S44、S47</td><td>S08、S09、S10、S27-S30、S45-S46、S48-S49</td><td>S04、S07-S10、S31、S44-S49</td><td>S04、S07-S10、S26-S31、S44-S49</td><td>三类各12例已覆盖，型号级诊断依据与授权边界待补</td></tr><tr><td>5. 设施检测</td><td>S05、S11、S26</td><td>S12、S13、S27-S30</td><td>S14、S31</td><td>S05、S11-S14、S26-S31</td><td>框架已覆盖，方法/仪器/判定依据待补</td></tr></tbody></table><blockquote><p>阅读训练时，先看基础卡，再看异常卡，最后复述恢复和记录要求。若题卡与现场设备说明书、检测方案或鉴定站评分表冲突，以适用的现场依据为准，并把差异记录下来。</p></blockquote><h2 id="四、统一证据字段" tabindex="-1">四、统一证据字段 <a class="header-anchor" href="#四、统一证据字段" aria-label="Permalink to &quot;四、统一证据字段&quot;">​</a></h2><p>每个标准条目和项目卡后续至少维护以下字段：</p><table tabindex="0"><thead><tr><th>字段</th><th>填写要求</th></tr></thead><tbody><tr><td><code>standardItem</code></td><td>标准编号或分项编号；未核验时不得伪造页码或原句</td></tr><tr><td><code>coursePage</code></td><td>对应理论/技能页面</td></tr><tr><td><code>projectCard</code></td><td>对应设备项目卡</td></tr><tr><td><code>trainingCard</code></td><td>对应只读训练题卡或场景卡</td></tr><tr><td><code>sourceRef</code></td><td>职业标准、大纲、教材、现行标准、设计文件或说明书链接</td></tr><tr><td><code>version</code></td><td>来源版本/发布日期/实施日期</td></tr><tr><td><code>verifiedAt</code></td><td>最近一次人工核验日期</td></tr><tr><td><code>status</code></td><td><code>已核验</code>、<code>框架已建</code>、<code>待原文复核</code>、<code>需地方公告核验</code></td></tr><tr><td><code>boundary</code></td><td>不适用场景、设备差异、地方评分表或安全授权边界</td></tr></tbody></table><h2 id="四、当前学习顺序" tabindex="-1">四、当前学习顺序 <a class="header-anchor" href="#四、当前学习顺序" aria-label="Permalink to &quot;四、当前学习顺序&quot;">​</a></h2><ol><li>先读<a href="/skill/01-monitoring">设施监控基础</a>，理解报警、故障、反馈和恢复；</li><li>再读<a href="/skill/05-detection">设施检测</a>，掌握检测前准备和五项结果；</li><li>接着读<a href="/skill/04-repair">设施维修</a>，掌握故障闭环与安全隔离；</li><li>回到报警、水系统和其他设施项目卡，按对象练习；</li><li>用<a href="/training-skill">技能只读训练</a>检查是否能说清步骤、反馈、恢复和记录；</li><li>最后根据报考地公告、考核大纲和现场评分表补齐当批次项目。</li></ol><h2 id="五、核验边界" tabindex="-1">五、核验边界 <a class="header-anchor" href="#五、核验边界" aria-label="Permalink to &quot;五、核验边界&quot;">​</a></h2><ul><li>不把本站原创题、场景卡或项目归类用语称为官方真题、官方评分表或标准原文。</li><li>不把施工验收参数直接改写成日常保养或维修的统一阈值。</li><li>不把某品牌按钮、地址编码、端子定义外推为所有设备通用步骤。</li><li>不把一次动作、一次观察或一次末端试水结果直接写成全系统合格。</li><li>涉及停用、放水、联动、气体灭火、电气拆装和机械运动时，必须服从授权、审批、监护和现场规程。</li></ul>',25)])])}const k=d(a,[["render",c]]);export{b as __pageData,k as default};
